package com.politeness.ading.ops.common;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * The ops console must verify password hashes produced by conductor, otherwise ops accounts can't log in.
 *
 * The hash below was really generated by conductor's PasswordEncoder (not made and verified by this module itself),
 * plaintext Ops#Verify-2026. It pins the format contract between both sides: if conductor changes the hash format, this test fails first.
 */
class PasswordVerifierTest {

    private static final String RAW = "Ops#Verify-2026";
    private static final String CONDUCTOR_HASH =
            "pbkdf2$120000$EXIeMApy+mqoOqgBWeL62Q==$kPrPah4YESaeKTPNsIAqKlfk2Nb3zugOLOFjceIzMAk=";

    private final PasswordVerifier verifier = new PasswordVerifier();

    @Test
    void acceptsTheHashConductorProduced() {
        assertTrue(verifier.matches(RAW, CONDUCTOR_HASH));
    }

    @Test
    void rejectsWrongPassword() {
        assertFalse(verifier.matches("Ops#Verify-2027", CONDUCTOR_HASH));
        assertFalse(verifier.matches("", CONDUCTOR_HASH));
        assertFalse(verifier.matches(RAW + " ", CONDUCTOR_HASH), "No trim: one extra space is a different password");
    }

    @Test
    void survivesMalformedStoredHashesWithoutThrowing() {
        assertFalse(verifier.matches(RAW, null));
        assertFalse(verifier.matches(null, CONDUCTOR_HASH));
        assertFalse(verifier.matches(RAW, "pbkdf2$120000$not-base64!$also-not-base64!"));
        assertFalse(verifier.matches(RAW, "pbkdf2$abc$EXIeMApy+mqoOqgBWeL62Q==$kPrPah4YESaeKTPNsIAqKlfk2Nb3zugOLOFjceIzMAk="));
        assertFalse(verifier.matches(RAW, "pbkdf2$0$EXIeMApy+mqoOqgBWeL62Q==$kPrPah4YESaeKTPNsIAqKlfk2Nb3zugOLOFjceIzMAk="));
        assertFalse(verifier.matches(RAW, "bcrypt$12$whatever"));
        assertFalse(verifier.matches(RAW, CONDUCTOR_HASH.substring(0, 40)), "A truncated hash doesn't match and doesn't throw");
    }

    @Test
    void readsIterationsFromTheHashSoConductorCanRaiseThemLater() {
        // The iteration count is fixed in the stored string; if conductor raises it later, old hashes still verify
        assertTrue(verifier.matches(RAW, CONDUCTOR_HASH), "120000 rounds");
    }
}
